CREATE OR ALTER procedure [dbo].[GetTechnicalRelationshipsByObject]
	@ResponsibleObjectType varchar(50),
	@ResponsibleObjectID int,
	@ObjectType varchar(50),
	@ObjectID int
as
begin
	declare @IntersectID int;

	select	@IntersectID = ID
	from	[Intersect]
	where	(Subject = @ResponsibleObjectType and SubjectID = @ResponsibleObjectID and Object = @ObjectType and ObjectID = @ObjectID) OR
			(Object = @ResponsibleObjectType and ObjectID = @ResponsibleObjectID and Subject = @ObjectType and SubjectID = @ObjectID);

	EXEC GetTechnicalRelationshipsByIntersect @IntersectID;
end

CREATE OR ALTER PROCEDURE [fusion].[ProcessFusionRelationships] @executionID int AS BEGIN set NOCOUNT, ANSI_PADDING ON; SET ANSI_WARNINGS ON;
declare @objectType varchar(50) = 'FusionAttribute';
delete T from fusion.StagingRelation T left join [Intersect] S on S.Subject = @objectType and S.Object = @objectType and ( ( S.SubjectID = T.StartFusionAttributeID and S.ObjectID = T.EndFusionAttributeID ) OR ( S.SubjectID = T.EndFusionAttributeID and S.ObjectID = T.StartFusionAttributeID ) ) where ExecutionID = @executionID and S.ID is null;
Declare @IDList Table(IntersectID int, StageID Int);
MERGE INTO [Intersect] d USING ( SELECT IntersectTypeID, ID, StartFusionAttributeID, EndFusionAttributeID FROM [fusion].stagingrelation where ExecutionID = @executionID and IntersectID is null ) S ON (1 = 0) WHEN NOT MATCHED THEN INSERT (IntersectTypeID, Subject, SubjectID, Object, ObjectID) VALUES (S.IntersectTypeID, @objectType, StartFusionAttributeID, @objectType, EndFusionAttributeID) OUTPUT INSERTED.ID, S.ID into @IDList;
UPDATE T SET T.IntersectID = S.IntersectID from [fusion].[StagingRelation] T inner join @IDList S on T.ExecutionID = @executionID and T.ID = S.StageID; END


CREATE OR ALTER FUNCTION [workflow].[ConditionToPlainText] 
(
	@ConditionXml xml	
)
RETURNS varchar(500)
AS
BEGIN	
	DECLARE @PlainText varchar(500) = '';
	DECLARE @Value varchar(500) = '';
	DECLARE @Operator varchar(500) = '';
	DECLARE @FieldName varchar(500) = '';
	DECLARE @FieldTypeID int;

	SELECT 
		@FieldTypeID = Child.value('(Condition[1]/@FieldTypeID)', 'int'),
		@Operator = Child.value('(Condition[1])/@Operator', 'Varchar(50)'),
		@Value = Child.value('(Condition[1])/@Value', 'Varchar(50)')
	FROM
		@ConditionXml.nodes('/Conditions') AS N(Child);


	if (@FieldTypeID > 0)
	begin
		select @FieldName = FriendlyName from fieldtype where id = @FieldTypeID;
	end

	RETURN @FieldName + ' ' +  @Operator + ' ' + @Value;
END


CREATE OR ALTER FUNCTION [utility].[GetFormattedFieldFusionQueryAttributeValueWrapper]
(
	@FusionQueryAttributeID int,
	@FusionQueryAttributeTypeID int	
)
RETURNS nvarchar(max)
AS
BEGIN
	return utility.GetFormattedFieldFusionQueryAttributeValue(@FusionQueryAttributeID, @FusionQueryAttributeTypeID)
END
